INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 25, 'theory', 'Квиз: libvirt-python');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 0, 'Чем метод shutdown домена отличается от destroy?', '["shutdown выдёргивает питание, destroy просит гостя выключиться", "Они равнозначны, различаются лишь именем", "shutdown лишь отправляет гостю просьбу и сразу возвращается, destroy немедленно обрывает работу", "shutdown удаляет определение домена, destroy его сохраняет"]', 2, 'shutdown — просьба гостю (он может её проигнорировать), поэтому состояние нужно опрашивать до срока. destroy похож на выдёргивание шнура питания: диски могут остаться в неконсистентном состоянии. Определение домена меняет undefine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 1, 'Как надёжнее всего отличить ошибку «нет такого домена» в скрипте?', '["Сравнить get_error_code() с VIR_ERR_NO_DOMAIN (42)", "Искать слово «not found» в тексте исключения", "Проверить тип исключения: это всегда KeyError", "Вызвать isActive() до lookupByName"]', 0, 'Все сбои приходят как libvirtError, а различает их числовой код. Текст сообщения предназначен людям и меняется от версии и языка. isActive() нельзя вызвать, пока домен не найден.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 2, 'Как получить загрузку процессора домена в процентах от его vCPU?', '["Взять cpuTime из info() и поделить на число vCPU", "Прочитать готовое поле «cpu_percent» из info()", "Поделить cpuTime на объём памяти домена", "Взять прирост cpuTime за интервал и поделить на (прошедшие наносекунды × число vCPU)"]', 3, 'cpuTime — накопительный счётчик в наносекундах, поэтому нужны два замера и разность. Её делят на прошедшее время и на число vCPU. Готового процента в info() нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 3, 'Что нужно сделать с циклом событий libvirt в Питоне?', '["Ничего: события приходят сами, как только вызван domainEventRegisterAny", "Зарегистрировать реализацию до открытия соединения и крутить virEventRunDefaultImpl в цикле", "Вызвать virEventRunDefaultImpl один раз после закрытия соединения", "Запускать цикл только из обработчика события"]', 1, 'Реализация цикла регистрируется до открытия соединения, а затем virEventRunDefaultImpl вызывают в цикле, обычно в потоке-демоне. Без этого обработчики не вызываются, а соединение может закрыться по тайм-ауту keepalive.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 4, 'Какой ключ в словаре getAllDomainStats описывает число байт, записанных на первый диск?', '["disk.0.written", "block.1.wr.bytes", "block.0.wr.bytes", "blockStats.wr_bytes"]', 2, 'Массивы нумеруются с нуля, ключ собирается из block.<номер>.wr.bytes, а число дисков лежит в block.count. block.1 — уже второй диск.');
